-- Bloco 8 (controle de estoque) e bloco 6 (baixa e estorno dos pedidos). SRS seção 6.
-- O saldo de cada ingrediente é sempre calculado: soma das ENTRADAS e ESTORNOS menos a soma das SAÍDAS (RF-031).
CREATE TABLE estoque_movimentacao (
  id BIGINT AUTO_INCREMENT PRIMARY KEY, ingrediente_id BIGINT NOT NULL, tipo VARCHAR(10) NOT NULL,
  quantidade DECIMAL(12,3) NOT NULL, motivo VARCHAR(20) NOT NULL, lote VARCHAR(60), validade DATE,
  custo_unitario DECIMAL(10,4), pedido_compra_id BIGINT NULL, pedido_id BIGINT NULL, usuario_id BIGINT NULL,
  observacao VARCHAR(255), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_mov_ingrediente FOREIGN KEY (ingrediente_id) REFERENCES ingrediente(id),
  CONSTRAINT fk_mov_pedido FOREIGN KEY (pedido_id) REFERENCES pedido(id),
  CONSTRAINT fk_mov_usuario FOREIGN KEY (usuario_id) REFERENCES usuario(id));
-- pedido_compra_id ganha a chave estrangeira no bloco 7, quando a tabela pedido_compra for criada.

-- Seed: estoque inicial. Polvo, Katsuobushi e Matcha começam ABAIXO do mínimo para mostrar os alertas (RF-032).
